1|// Deterministic k-means over scene features. Same input gives
2|// byte-identical output: seeded init, fixed restarts, sorted naming.
3|import { EMOTIONS, FEATURE_WEIGHTS } from "./types";
4|import type { EmotionId, Vector8 } from "./types";
5|
6|export interface WeightedPoint {
7|  sceneId: string;
8|  features: number[]; // 8 vector values, then intensity, then tempo
9|}
10|
11|export interface KmeansCluster {
12|  points: WeightedPoint[];
13|  centroid: number[];
14|  inertia: number;
15|}
16|
17|export function mulberry32(seed: number): () => number {
18|  let state = seed >>> 0;
19|  return () => {
20|    state = (state + 0x6d2b79f5) >>> 0;
21|    let t = state;
22|    t = Math.imul(t ^ (t >>> 15), t | 1);
23|    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
24|    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
25|  };
26|}
27|
28|// Intensity and tempo each weigh half an emotion slot, so mood still
29|// decides the grouping while energy breaks ties.
30|export function buildFeatures(input: { vector: Vector8; intensity: number; tempo: number }): number[] {
31|  const features = EMOTIONS.map((id: EmotionId) => input.vector[id]);
32|  features.push(input.intensity * FEATURE_WEIGHTS.intensity);
33|  features.push(input.tempo * FEATURE_WEIGHTS.tempo);
34|  return features;
35|}
