37|function distance(a: number[], b: number[]): number {
38|  let sum = 0;
39|  for (let i = 0; i < a.length; i++) {
40|    const diff = (a[i] ?? 0) - (b[i] ?? 0);
41|    sum += diff * diff;
42|  }
43|  return sum;
44|}
45|
46|function mean(points: WeightedPoint[]): number[] {
47|  const dims = points[0]?.features.length ?? 0;
48|  const centroid = new Array<number>(dims).fill(0);
49|  for (const point of points) {
50|    for (let d = 0; d < dims; d++) centroid[d] = (centroid[d] ?? 0) + (point.features[d] ?? 0);
51|  }
52|  return centroid.map((value) => value / points.length);
53|}
54|
55|function kmeansPlusPlus(points: WeightedPoint[], k: number, rand: () => number): number[][] {
56|  const centroids: number[][] = [];
57|  centroids.push([...(points[Math.floor(rand() * points.length)]?.features ?? [])]);
58|  while (centroids.length < k) {
59|    const weights = points.map((p) => Math.min(...centroids.map((c) => distance(p.features, c))));
60|    const total = weights.reduce((a, b) => a + b, 0);
61|    if (total <= 0) {
62|      centroids.push([...(points[centroids.length % points.length]?.features ?? [])]);
63|      continue;
64|    }
65|    let pick = rand() * total;
66|    let chosen = points[points.length - 1]?.features ?? [];
67|    for (let i = 0; i < points.length; i++) {
68|      pick -= weights[i] ?? 0;
69|      if (pick <= 0) {
70|        chosen = points[i]?.features ?? [];
71|        break;
72|      }
73|    }
74|    centroids.push([...chosen]);
75|  }
76|  return centroids;
77|}
78|
79|export function kmeans(
80|  points: WeightedPoint[],
81|  k: number,
82|  opts?: { seed?: number; restarts?: number; maxIter?: number },
83|): KmeansCluster[] {
84|  const seed = opts?.seed ?? 42;
85|  const restarts = opts?.restarts ?? 20;
86|  const maxIter = opts?.maxIter ?? 100;
87|  if (points.length === 0 || k <= 0) return [];
88|  const clampedK = Math.min(k, points.length);
89|  let best: KmeansCluster[] | null = null;
90|  for (let r = 0; r < restarts; r++) {
91|    const rand = mulberry32(seed + r);
92|    let centroids = kmeansPlusPlus(points, clampedK, rand);
93|    let assign = new Array<number>(points.length).fill(0);
94|    for (let iter = 0; iter < maxIter; iter++) {
95|      const next = points.map((p) => {
96|        let bi = 0;
97|        let bd = Infinity;
98|        centroids.forEach((c, i) => {
99|          const d = distance(p.features, c);
100|          if (d < bd) {
101|            bd = d;
102|            bi = i;
103|          }
104|        });
105|        return bi;
106|      });
107|      // An empty cluster restarts at the point farthest from its centroid.
108|      const counts = new Array<number>(clampedK).fill(0);
109|      for (const a of next) counts[a] = (counts[a] ?? 0) + 1;
110|      for (let c = 0; c < clampedK; c++) {
111|        if ((counts[c] ?? 0) === 0) {
112|          let far = 0;
113|          let farD = -1;
114|          points.forEach((p, i) => {
115|            const d = distance(p.features, centroids[next[i] ?? 0] ?? []);
116|            if (d > farD) {
117|              farD = d;
118|              far = i;
119|            }
120|          });
121|          centroids[c] = [...(points[far]?.features ?? [])];
122|          next[far] = c;
123|        }
124|      }
125|      const moved = next.some((a, i) => a !== assign[i]);
126|      assign = next;
127|      const groups = centroids.map((_, c) => points.filter((_, i) => assign[i] === c));
128|      centroids = groups.map((g, c) => (g.length > 0 ? mean(g) : (centroids[c] ?? [])));
129|      if (!moved) break;
130|    }
131|    const candidate: KmeansCluster[] = centroids.map((centroid, c) => {
132|      const members = points.filter((_, i) => assign[i] === c);
133|      const inertia = members.reduce((sum, p) => sum + distance(p.features, centroid), 0);
134|      return { points: members, centroid, inertia };
135|    });
136|    const total = candidate.reduce((sum, c) => sum + c.inertia, 0);
137|    if (best === null || total < best.reduce((sum, c) => sum + c.inertia, 0)) best = candidate;
138|  }
139|  return best ?? [];
140|}
141|
142|// Dominant emotion index decides cluster order, then intensity.
143|export function dominantIndex(centroid: number[]): number {
144|  let best = 0;
145|  let bestValue = -Infinity;
146|  for (let i = 0; i < EMOTIONS.length; i++) {
147|    const value = centroid[i] ?? 0;
148|    if (value > bestValue) {
149|      bestValue = value;
150|      best = i;
151|    }
152|  }
153|  return best;
