2|export function paragraphId(chapter: number, para: number): string {
3|  if (!Number.isInteger(chapter) || chapter < 1 || !Number.isInteger(para) || para < 1) {
4|    throw new RangeError(`paragraphId needs positive integers, got ${chapter}, ${para}`);
5|  }
