1|// Scene coverage validators. Problems are data, not throws, so the
2|// caller can paste them into the retry prompt and then fail loudly.
3|import type { Book, Chapter, Scene, SceneInput } from "./types";
4|
5|export interface CoverageProblem {
6|  code: "gap" | "overlap" | "bad-start" | "bad-end" | "order" | "cross-chapter" | "out-of-range";
7|  message: string;
8|}
9|
10|export function validateSceneCoverage(chapter: Chapter, scenes: SceneInput[]): CoverageProblem[] {
11|  const problems: CoverageProblem[] = [];
12|  if (scenes.length === 0) {
13|    problems.push({ code: "gap", message: `chapter ${chapter.ch} has no scenes` });
14|    return problems;
15|  }
16|  const first = scenes[0];
17|  if (first && first.start_n !== chapter.start_n) {
18|    problems.push({
19|      code: "bad-start",
20|      message: `first scene starts at ${first.start_n}, chapter starts at ${chapter.start_n}`,
21|    });
22|  }
23|  scenes.forEach((scene, i) => {
24|    if (scene.start_n < chapter.start_n || scene.end_n > chapter.end_n) {
25|      problems.push({
26|        code: "out-of-range",
27|        message: `scene ${i} [${scene.start_n}..${scene.end_n}] outside chapter [${chapter.start_n}..${chapter.end_n}]`,
28|      });
29|    }
30|    if (scene.start_n > scene.end_n) {
31|      problems.push({ code: "order", message: `scene ${i} starts after it ends` });
32|    }
33|    if (i === 0) return;
34|    const prev = scenes[i - 1];
35|    if (prev && scene.start_n === prev.end_n + 1) return;
36|    if (prev && scene.start_n <= prev.end_n) {
37|      problems.push({ code: "overlap", message: `scene ${i} starts at ${scene.start_n} inside previous scene ending at ${prev.end_n}` });
38|    } else if (prev) {
39|      problems.push({ code: "gap", message: `gap between scene ${i - 1} ending at ${prev.end_n} and scene ${i} starting at ${scene.start_n}` });
40|    }
41|  });
42|  const last = scenes[scenes.length - 1];
43|  if (last && last.end_n !== chapter.end_n) {
44|    problems.push({
45|      code: "bad-end",
46|      message: `last scene ends at ${last.end_n}, chapter ends at ${chapter.end_n}`,
47|    });
48|  }
49|  return problems;
50|}
