52|// Whole book check: no scene crosses a chapter, and the union covers
53|// every paragraph exactly once.
54|export function validateBookCoverage(
55|  book: Pick<Book, "chapters" | "paragraphs">,
56|  scenes: Scene[],
57|): CoverageProblem[] {
58|  const problems: CoverageProblem[] = [];
59|  const byCh = new Map(book.chapters.map((c) => [c.ch, c]));
60|  const total = book.paragraphs.length;
61|  const seen = new Array<boolean>(total + 1).fill(false);
62|  for (const scene of scenes) {
63|    const chapter = byCh.get(scene.ch);
64|    if (!chapter) {
65|      problems.push({ code: "cross-chapter", message: `scene ${scene.id} names unknown chapter ${scene.ch}` });
66|      continue;
67|    }
68|    if (scene.start_n < chapter.start_n || scene.end_n > chapter.end_n) {
69|      problems.push({ code: "cross-chapter", message: `scene ${scene.id} crosses chapter ${scene.ch} bounds` });
70|    }
71|    for (let n = scene.start_n; n <= scene.end_n; n++) {
72|      if (n < 1 || n > total) {
73|        problems.push({ code: "out-of-range", message: `scene ${scene.id} covers ordinal ${n} outside 1..${total}` });
74|        continue;
75|      }
76|      if (seen[n]) {
77|        problems.push({ code: "overlap", message: `ordinal ${n} covered twice` });
78|      }
79|      seen[n] = true;
80|    }
81|  }
82|  for (let n = 1; n <= total; n++) {
83|    if (!seen[n]) problems.push({ code: "gap", message: `ordinal ${n} covered by no scene` });
84|  }
